import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

# Extract packages per project/framework
def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (name, tfm, pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)

changes = []
for k in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(k, 'N/A')
    av = a.get(k, 'N/A')
    if bv != av:
        changes.append((k, bv, av))

if changes:
    print('VERSION CHANGES:')
    for (proj, tfm, pkg), bv, av in changes:
        print(f'  {proj} ({tfm}) {pkg}: {bv} -> {av}')
else:
    print('No version changes - conversion is version-neutral for projects that already used highest versions.')

# Show projects that got upgraded
print()
print('Projects aligned to highest version:')
for (proj, tfm, pkg), bv, av in changes:
    if bv != 'N/A' and av != 'N/A':
        print(f'  {proj} ({tfm}) {pkg}: {bv} -> {av}')
